import{_ as t,c as l,o,a9 as r}from"./chunks/framework.GQWhFI7o.js";const c=JSON.parse('{"title":"微软应用商店上架指南","description":"","frontmatter":{"createDate":"2026/04/23","tags":"微软应用商店, MSIX, 代码签名"},"headers":[],"relativePath":"技术的小记/微软应用商店上架指南/index.md","filePath":"技术的小记/微软应用商店上架指南/index.md","lastUpdated":1776958841000}'),i={name:"技术的小记/微软应用商店上架指南/index.md"};function e(s,a,n,p,d,h){return o(),l("div",null,a[0]||(a[0]=[r('<h1 id="微软应用商店上架指南" tabindex="-1">微软应用商店上架指南 <a class="header-anchor" href="#微软应用商店上架指南" aria-label="Permalink to &quot;微软应用商店上架指南&quot;">​</a></h1><p>2026年04月23日</p><nav class="table-of-contents"><ul><li><a href="#为什么-msix-格式更值得选择">为什么 MSIX 格式更值得选择</a><ul><li><a href="#签名成本的天壤之别">签名成本的天壤之别</a></li><li><a href="#技术栈的现实困境">技术栈的现实困境</a></li></ul></li><li><a href="#使用-msix-packaging-tool-完成转换">使用 MSIX Packaging Tool 完成转换</a><ul><li><a href="#步骤一-选择任务类型">步骤一：选择任务类型</a></li><li><a href="#步骤二-选择打包环境">步骤二：选择打包环境</a></li><li><a href="#步骤三-指定安装程序">步骤三：指定安装程序</a></li><li><a href="#步骤四-填写程序包信息">步骤四：填写程序包信息</a></li><li><a href="#转换完成后会发生什么">转换完成后会发生什么</a></li></ul></li><li><a href="#进阶技巧-使用-msix-hero-进行本地验证">进阶技巧：使用 MSIX Hero 进行本地验证</a></li><li><a href="#结语">结语</a></li></ul></nav><p>微软应用商店是目前各软件分发平台中，上架应用成本最低的。除了注册免费以外，代码签名也可以做到免费。但并不是所有 Windows 软件都可以享受免费签名，只有 MSIX 格式的软件包能够享受这个优惠。本文教你怎么做。</p><p>开始之前，先来认识几个关键名词：</p><ul><li><p><strong>Microsoft Store</strong>：微软应用商店，Windows 10/11 系统内置的应用分发平台，开发者可将应用提交至商店供用户下载安装。</p></li><li><p><strong>EXE</strong>：Windows 可执行文件格式，是最常见的应用程序安装程序格式。</p></li><li><p><strong>MSI</strong>：Windows Installer 安装包格式，基于 Microsoft Installer 技术，支持更复杂的安装逻辑和回滚机制。</p></li><li><p><strong>MSIX</strong>：微软推出的现代应用程序打包格式，结合了 MSI、MSIX、APP-V 和 ClickOnce 的优势，支持原子安装/卸载、自动更新、沙箱隔离等特性。</p></li><li><p><strong>PWA</strong>：Progressive Web App（渐进式 Web 应用），基于 Web 技术构建的应用程序，可通过浏览器安装并具备接近原生应用的能力。</p></li><li><p><strong>代码签名</strong>：使用数字证书对应用程序进行签名，以验证软件来源的真实性和完整性。微软商店要求上架的应用必须经过签名。</p></li></ul><hr><h2 id="为什么-msix-格式更值得选择" tabindex="-1">为什么 MSIX 格式更值得选择 <a class="header-anchor" href="#为什么-msix-格式更值得选择" aria-label="Permalink to &quot;为什么 MSIX 格式更值得选择&quot;">​</a></h2><h3 id="签名成本的天壤之别" tabindex="-1">签名成本的天壤之别 <a class="header-anchor" href="#签名成本的天壤之别" aria-label="Permalink to &quot;签名成本的天壤之别&quot;">​</a></h3><p>上架微软应用商店，安装包格式的选择直接决定了你的钱包和心情：</p><ul><li><p><strong>EXE 和 MSI 应用</strong>：需要提前购买代码签名证书。受信任的 EV 证书价格不菲，每年动辄数千元；申请流程也相当繁琐，企业身份验证、材料提交一样不能少。</p></li><li><p><strong>MSIX 和 PWA 应用</strong>：微软直接提供免费签名服务。应用提交后，微软会在分发时自动完成签名，开发者省去了购买证书的开销和精力。</p></li></ul><p>对于预算有限或个人开发者来说，MSIX 格式无疑是更明智的选择。</p><h3 id="技术栈的现实困境" tabindex="-1">技术栈的现实困境 <a class="header-anchor" href="#技术栈的现实困境" aria-label="Permalink to &quot;技术栈的现实困境&quot;">​</a></h3><p>但并非所有开发框架都原生支持 MSIX 打包。以 Tauri 为例，打包命令生成的格式只能是 EXE 或 MSI 格式，没有 MSIX 选项。</p><p>当你遇到这种尴尬局面时，不必慌张，微软提供了专门的工具来帮你完成格式转换。</p><hr><h2 id="使用-msix-packaging-tool-完成转换" tabindex="-1">使用 MSIX Packaging Tool 完成转换 <a class="header-anchor" href="#使用-msix-packaging-tool-完成转换" aria-label="Permalink to &quot;使用 MSIX Packaging Tool 完成转换&quot;">​</a></h2><p>Microsoft 官方提供的 <strong>MSIX Packaging Tool</strong> 正是为这种场景而生。它能够将现有的 EXE 或 MSI 安装包转换为 MSIX 格式。下面以 MSI 转 MSIX 为例，带你走一遍完整流程。</p><h3 id="步骤一-选择任务类型" tabindex="-1">步骤一：选择任务类型 <a class="header-anchor" href="#步骤一-选择任务类型" aria-label="Permalink to &quot;步骤一：选择任务类型&quot;">​</a></h3><p>打开 MSIX Packaging Tool，主界面呈现三个选项：</p><p><img src="https://dev-to-uploads.s3.amazonaws.com/uploads/articles/pr9k8vt0mezvij3mqacs.png" alt="选择任务" loading="lazy"></p><ul><li><strong>应用程序包</strong>：从零创建新的应用程序包，适合从现有安装程序转换的场景。</li><li><strong>修改程序包</strong>：可修改现有应用的程序包。</li><li><strong>程序包编辑器</strong>：编辑已有的 MSIX 程序包。</li></ul><p>选择<strong>应用程序包</strong>，开启转换之旅。</p><h3 id="步骤二-选择打包环境" tabindex="-1">步骤二：选择打包环境 <a class="header-anchor" href="#步骤二-选择打包环境" aria-label="Permalink to &quot;步骤二：选择打包环境&quot;">​</a></h3><p>接下来需要确定在什么环境中进行打包：</p><p><img src="https://dev-to-uploads.s3.amazonaws.com/uploads/articles/l4z1ek0nln2ayyiyy19r.png" alt="选择环境" loading="lazy"></p><p>三种环境各有特点：</p><ul><li><strong>在此计算机上创建程序包</strong>：直接在本地操作，简单快捷，但可能会在本地留下安装痕迹。</li><li><strong>在远程计算机上创建程序包</strong>：在远程机器上打包，适合团队协作或需要特定环境的场景。</li><li><strong>在本地虚拟机上创建程序包</strong>：通过 Hyper-V 虚拟机打包，最干净的方式，完全不影响主机环境。</li></ul><p>对于大多数转换需求，选择<strong>在此计算机上创建程序包</strong>即可满足。</p><h3 id="步骤三-指定安装程序" tabindex="-1">步骤三：指定安装程序 <a class="header-anchor" href="#步骤三-指定安装程序" aria-label="Permalink to &quot;步骤三：指定安装程序&quot;">​</a></h3><p>这一步需要告诉工具你要转换哪个安装包：</p><p><img src="https://dev-to-uploads.s3.amazonaws.com/uploads/articles/k21bvr3v8e7m513ij6vf.png" alt="选择安装程序" loading="lazy"></p><p>操作要点：</p><ul><li>点击<strong>浏览</strong>按钮，找到并选择目标 MSI 文件。</li><li><strong>指定安装程序参数</strong>：这是一个可选字段。如果你的安装包需要特殊参数（比如自定义安装路径或静默安装模式），可以在此输入。</li><li><strong>签名首选项</strong>：下拉菜单中选择签名方式。既然微软商店提供免费签名，这里直接选择<strong>不对程序包进行签名</strong>即可。</li></ul><h3 id="步骤四-填写程序包信息" tabindex="-1">步骤四：填写程序包信息 <a class="header-anchor" href="#步骤四-填写程序包信息" aria-label="Permalink to &quot;步骤四：填写程序包信息&quot;">​</a></h3><p>最后一步是为你的 MSIX 包填写&quot;身份证&quot;信息：</p><p><img src="https://dev-to-uploads.s3.amazonaws.com/uploads/articles/i0qs4cpx1im3o6zmyu41.png" alt="程序包信息" loading="lazy"></p><p>需要填写的字段如下：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>程序包名称</td><td>MSIX 包的技术名称，通常采用反向域名格式，如 com.example.myapp</td></tr><tr><td>程序包显示名称</td><td>用户在商店中看到的应用名称</td></tr><tr><td>发布者名称</td><td>发布者的技术名称，与签名证书相关联</td></tr><tr><td>发布者显示名称</td><td>商店中显示的开发者或公司名称</td></tr><tr><td>版本</td><td>应用版本号，遵循 Major.Minor.Build.Revision 格式</td></tr><tr><td>程序包描述</td><td>简短介绍应用的功能和特点</td></tr><tr><td>安装位置</td><td>应用程序默认安装到的目录</td></tr></tbody></table><p>还有一个实用选项：<strong>将对 MSIX Core 的支持添加到此包中</strong>。MSIX Core 是微软开源的运行时组件，能让 MSIX 包在不原生支持该格式的旧版 Windows 上运行。如果你的目标用户群体包含较老系统的用户，建议勾选此项。</p><blockquote><p><strong>提醒</strong>：填写完信息并点击下一步后，安装过程将立即开始，且无法返回修改。请务必仔细核对所有字段。</p></blockquote><h3 id="转换完成后会发生什么" tabindex="-1">转换完成后会发生什么 <a class="header-anchor" href="#转换完成后会发生什么" aria-label="Permalink to &quot;转换完成后会发生什么&quot;">​</a></h3><p>配置完成后，MSIX Packaging Tool 会在后台完成以下工作：</p><ol><li>运行你指定的安装程序</li><li>全程监控安装过程中对文件系统和注册表的所有更改</li><li>安装结束后，捕获这些变更并重新打包为 MSIX 格式</li><li>生成首次启动任务配置（可选）</li><li>输出最终的 MSIX 安装包</li></ol><hr><h2 id="进阶技巧-使用-msix-hero-进行本地验证" tabindex="-1">进阶技巧：使用 MSIX Hero 进行本地验证 <a class="header-anchor" href="#进阶技巧-使用-msix-hero-进行本地验证" aria-label="Permalink to &quot;进阶技巧：使用 MSIX Hero 进行本地验证&quot;">​</a></h2><p>MSIX 包生成后，如果希望提高审核通过率，可以使用 <strong>MSIX Hero</strong> 这款免费工具进行本地验证。</p><p>MSIX Hero 提供以下实用功能：</p><ul><li>检查 MSIX 包的结构完整性和有效性</li><li>浏览包内包含的所有文件和注册表项</li><li>验证包是否符合微软商店的上架规范</li><li>在本地环境中安装和卸载 MSIX 包进行实测</li></ul><p>这一步虽非强制，但提前发现并解决问题，能显著降低被微软审核驳回的风险。毕竟，谁也不想反复提交、反复等待。</p><hr><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>回顾整个过程，核心要点可以归结为三点：</p><ol><li><strong>选择正确的格式</strong>：MSIX 和 PWA 享受微软免费签名，相比 EXE/MSI 节省大量成本。</li><li><strong>善用转换工具</strong>：MSIX Packaging Tool 能将 MSI/EXE 无损转换为 MSIX，弥补框架打包能力的不足。</li><li><strong>提前本地验证</strong>：MSIX Hero 帮你揪出潜在问题，减少审核往返次数。</li></ol><p>掌握这些技巧后，上架微软应用商店不再是一道难题。</p>',55)]))}const u=t(i,[["render",e]]);export{c as __pageData,u as default};
